PREFIX : <http://www.semanticweb.org/ronaldo/ontologies/2026/3/ontologia_medicamentos.owl#>
 PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> ASK WHERE {:mae_Ronaldo :usaMedicamento ?medicamentoAtual . ?medicamentoAtual :temPrincipioAtivo ?paAtual . :alivium rdf:type :Principio_Ativo . { ?paAtual :interageCom :alivium . } UNION { :alivium :interageCom ?paAtual .} 
}

